  const axe = bot.inventory.items().find(i => i.name.endsWith('_axe'));
  if (axe) {
    await bot.equip(axe, 'hand');
  }
  await bot.lookAt(block.position.offset(0.5, 0.5, 0.5));
  await bot.dig(block);
  return true;
};

